using System;using System.IO;using System.Linq;using HarmonyLib;using MDPro3;using MDPro3.Duel;using MDPro3.Servant;
namespace DuelStructure {
 static class NativeChainState {
  public static int LastDisabledCode;
  internal sealed class Link {public int Code;public byte Player,Location,Sequence,Position,TriggerPlayer;}
  internal static Link[] Read(byte[] payload){using(var reader=new BinaryReader(new MemoryStream(payload))){reader.ReadByte();for(int p=0;p<2;p++){reader.ReadInt32();for(int i=0;i<7;i++)if(reader.ReadByte()!=0)reader.ReadBytes(2);for(int i=0;i<8;i++)if(reader.ReadByte()!=0)reader.ReadByte();reader.ReadBytes(6);}int count=reader.ReadByte();var result=new Link[count];for(int i=0;i<count;i++){var link=new Link{Code=reader.ReadInt32(),Player=reader.ReadByte(),Location=reader.ReadByte(),Sequence=reader.ReadByte(),Position=reader.ReadByte(),TriggerPlayer=reader.ReadByte()};reader.ReadBytes(6);result[i]=link;}return result;}}
  internal static void Restore(Link[] links){if(Host.Session==null||links==null)return;var core=Program.instance.ocgcore;var log=core.messageDispatcher.log;OcgCore.cardsInChain.Clear();OcgCore.codesInChain.Clear();OcgCore.controllerInChain.Clear();OcgCore.negatedInChain.Clear();log.cardsInChain.Clear();int view=Host.Session.View;for(int i=0;i<links.Length;i++){var link=links[i];var gps=new GPS{controller=link.Player==view?0u:1u,location=link.Location,sequence=link.Sequence,position=link.Position};var card=core.GCS_Get(gps)??core.GCS_Create(gps,true);if(card!=null){card.SetCode(link.Code);card.AddChain(i+1);}OcgCore.cardsInChain.Add(card);OcgCore.codesInChain.Add(link.Code);OcgCore.controllerInChain.Add(link.TriggerPlayer==view?0u:1u);log.cardsInChain.Add(card);}Plugin.Instance.Log.LogInfo("EDITOR_CHAIN_RESTORE view="+view+" codes="+string.Join(",",links.Select(l=>l.Code)));}
 }
 [HarmonyPatch(typeof(DuelMessage),nameof(DuelMessage.GameMessage_ChainDisabled))]class TraceEditorChainDisabled {static void Prefix(Il2CppSystem.IO.BinaryReader reader){if(Host.Session==null)return;long pos=reader.BaseStream.Position;int index=reader.ReadByte();reader.BaseStream.Position=pos;NativeChainState.LastDisabledCode=index>0&&index<=OcgCore.codesInChain.Count?OcgCore.codesInChain[index-1]:0;Plugin.Instance.Log.LogInfo("EDITOR_CHAIN_DISABLED index="+index+" code="+NativeChainState.LastDisabledCode);}}
}
